		const actualPaintedRef = await uploadImage(outputData.paintedImage, sourceRef);
		const actualPaintedMaskedRef = await uploadMask(outputData.paintedMaskedImage, actualPaintedRef);
		outputData.maskedImage.ref = actualMaskedRef;
